 * Each declaration can be a simple string (the variable name) or a {@link VariableConfig}.
 */
const ENV_VAR_DECLARATIONS = [
  "CI_PROJECT_ID",
  "CI_PIPELINE_IID",
  {
    name: "CI_COMMIT_REF_NAME",
    local: async () => {
      const output = await $`git rev-parse --abbrev-ref HEAD`;
